import { z } from 'zod';
import { createThemeVersionSchema, latestThemeVersions } from '../properties/theme-version.js';
import { standardConfigSchema } from './reusable/index.js';
import { themeSchema } from './themes.js';
export const mintConfigSchema = z.object(Object.assign({ theme: z.literal(themeSchema.enum.mint), themeVersion: createThemeVersionSchema(latestThemeVersions.mint).optional() }, standardConfigSchema));
